const item = $input.first().json;
let payload = {};

if (item.content) {
  try {
    payload = typeof item.content === 'string' ? JSON.parse(item.content) : item.content;
  } catch (err) {
    payload = {};
  }
} else {
  payload = item;
}

const routingKey = item.fields?.routingKey || payload.eventType || '';
const data = payload.data || {};
const leadId = data.leadId || payload.leadId || null;
const workflowRunId = data.workflowRunId || payload.workflowRunId || null;
const eventType = payload.eventType || routingKey || '';

return [{
  json: {
    eventId: payload.eventId || null,
    eventType,
    routingKey,
    data,
    leadId,
    workflowRunId,
    provider: data.provider || payload.provider || 'mock',
    email: data.email || payload.email || null,
    companyName: data.companyName || payload.companyName || null,
    companyWebsite: data.companyWebsite || payload.companyWebsite || null,
    rawEvent: payload
  }
}];

const lead = $input.first().json;
const parsedEvent = $('Parse Event Payload').first().json || {};
const triggerData = parsedEvent.data || {};

const rawEmail = (lead.email || parsedEvent.email || triggerData.email || '').trim().toLowerCase();
let emailDomain = '';
if (rawEmail.includes('@')) {
  emailDomain = rawEmail.split('@')[1];
}

const freeEmailProviders = new Set([
  'gmail.com',
  'yahoo.com',
  'hotmail.com',
  'outlook.com',
  'live.com',
  'icloud.com',
  'mail.com',
  'aol.com'
]);
const isFreeEmail = freeEmailProviders.has(emailDomain);

let websiteDomain = '';
const rawWebsite = (lead.companyWebsite || parsedEvent.companyWebsite || triggerData.companyWebsite || '').trim();
if (rawWebsite) {
  websiteDomain = rawWebsite
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split('/')[0]
    .split('?')[0]
    .toLowerCase();
}

const targetDomain = websiteDomain || (!isFreeEmail ? emailDomain : '');
const fallbackCompanyName = targetDomain
  ? targetDomain.split('.')[0].charAt(0).toUpperCase() + targetDomain.split('.')[0].slice(1)
  : 'Unknown Company';

const companyName = (lead.companyName || parsedEvent.companyName || triggerData.companyName || fallbackCompanyName).trim();
const provider = parsedEvent.provider || triggerData.provider || 'mock';

return [{
  json: {
    leadId: lead.id,
    workflowRunId: parsedEvent.workflowRunId || triggerData.workflowRunId || null,
    provider,
    email: rawEmail,
    emailDomain,
    isFreeEmail,
    domain: targetDomain || 'enterprise.com',
    companyName,
    jobTitle: lead.jobTitle || null,
    leadSnapshot: lead
  }
}];

const response = $input.first().json;
const prep = $('Normalize Email & Domain').first().json;

// Check if HTTP request failed
if (response.error || response.statusCode >= 400) {
  const errMsg = response.error?.message || response.message || 'External enrichment service call failed after retries';
  return [{
    json: {
      leadId: prep.leadId,
      workflowRunId: prep.workflowRunId,
      status: 'FAILED',
      provider: prep.provider,
      externalRequestId: null,
      companyName: null,
      companyWebsite: null,
      companyIndustry: null,
      companySize: null,
      contactJobTitle: null,
      contactLinkedinUrl: null,
      rawResponse: response,
      errorMessage: errMsg
    }
  }];
}

// Handle standard enrichment response schema
const company = response.company || {};
const contact = response.contact || {};
const enrichedCompanyName = company.name || response.companyName || prep.companyName || null;
const enrichedCompanyWebsite = company.website || response.companyWebsite || (prep.domain ? `https://${prep.domain}` : null);
const enrichedIndustry = company.industry || response.industry || response.companyIndustry || null;
const enrichedCompanySize = typeof company.size === 'number' ? company.size : (typeof response.companySize === 'number' ? response.companySize : null);
const enrichedJobTitle = contact.jobTitle || response.contactJobTitle || prep.jobTitle || null;
const enrichedLinkedinUrl = contact.linkedinUrl || response.contactLinkedinUrl || null;

const hasFullCompanyData = Boolean(enrichedCompanyName && enrichedIndustry && enrichedCompanySize);
const status = hasFullCompanyData ? 'SUCCESS' : (enrichedCompanyName ? 'PARTIAL' : 'FAILED');

return [{
  json: {
    leadId: prep.leadId,
    workflowRunId: prep.workflowRunId,
    status,
    provider: response.provider || prep.provider,
    externalRequestId: response.externalRequestId || null,
    companyName: enrichedCompanyName,
    companyWebsite: enrichedCompanyWebsite,
    companyIndustry: enrichedIndustry,
    companySize: enrichedCompanySize,
    contactJobTitle: enrichedJobTitle,
    contactLinkedinUrl: enrichedLinkedinUrl,
    rawResponse: response.rawResponse || response,
    errorMessage: status === 'FAILED' ? 'Enrichment returned empty or invalid company data' : null
  }
}];
